                grid[i] = line.toCharArray();
            }

            boolean[][] rowCheck = new boolean[9][10]; // rowCheck[row][num]
            boolean[][] colCheck = new boolean[9][10]; // colCheck[col][num]
            boolean[][] boxCheck = new boolean[9][10]; // boxCheck[boxIndex][num]

            boolean[][] error = new boolean[9][9]; // error[row][col]

