                for (int j = 0; j < 9; j++) {
                    a[i][j] = s.charAt(j) - '0';
                }
            }

            boolean[][] bad = new boolean[9][9];

            // Check rows
            for (int i = 0; i < 9; i++) {
                int[] cnt = new int[10];
                for (int j = 0; j < 9; j++) cnt[a[i][j]]++;
                for (int j = 0; j < 9; j++) {
                    if (cnt[a[i][j]] > 1) bad[i][j] = true;
                }
            }

            // Check columns
            for (int j = 0; j < 9; j++) {
                int[] cnt = new int[10];
                for (int i = 0; i < 9; i++) cnt[a[i][j]]++;
                for (int i = 0; i < 9; i++) {
                    if (cnt[a[i][j]] > 1) bad[i][j] = true;
                }
            }

            // Check 3x3 blocks
            for (int bi = 0; bi < 3; bi++) {
                for (int bj = 0; bj < 3; bj++) {
                    int[] cnt = new int[10];
                    for (int i = bi * 3; i < bi * 3 + 3; i++) {
                        for (int j = bj * 3; j < bj * 3 + 3; j++) {
                            cnt[a[i][j]]++;
                        }
                    }
                    for (int i = bi * 3; i < bi * 3 + 3; i++) {
                        for (int j = bj * 3; j < bj * 3 + 3; j++) {
                            if (cnt[a[i][j]] > 1) bad[i][j] = true;
                        }
                    }
                }
            }

            if (tc > 0) out.append('\n');

            for (int i = 0; i < 9; i++) {
                for (int j = 0; j < 9; j++) {
                    out.append(bad[i][j] ? '*' : ' ');
                    out.append(a[i][j]);
                }
                out.append('\n');
            }
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st;

        String next() throws Exception {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }
}

