import sys

def main():
    lines = [line.rstrip('\n') for line in sys.stdin]
    if not lines:
        return

    t = int(lines[0].strip())
    idx = 1
    out = []

    for case in range(t):
        grid = []
        for _ in range(9):
            # Remove spaces if any; puzzle rows are digits 1-9
            row = ''.join(lines[idx].split())
            idx += 1
            grid.append(row)

        bad = [[False] * 9 for _ in range(9)]

        # Check rows
        for r in range(9):
            pos = [[] for _ in range(10)]
            for c in range(9):
                d = int(grid[r][c])
                pos[d].append(c)
            for d in range(1, 10):
                if len(pos[d]) > 1:
                    for c in pos[d]:
                        bad[r][c] = True

        # Check columns
        for c in range(9):
            pos = [[] for _ in range(10)]
            for r in range(9):
                d = int(grid[r][c])
                pos[d].append(r)
            for d in range(1, 10):
                if len(pos[d]) > 1:
                    for r in pos[d]:
                        bad[r][c] = True

        # Check 3x3 blocks
        for br in range(0, 9, 3):
            for bc in range(0, 9, 3):
                pos = [[] for _ in range(10)]
                for r in range(br, br + 3):
                    for c in range(bc, bc + 3):
                        d = int(grid[r][c])
                        pos[d].append((r, c))
                for d in range(1, 10):
                    if len(pos[d]) > 1:
                        for r, c in pos[d]:
                            bad[r][c] = True

        # Output transformed grid
        for r in range(9):
            line = []
            for c in range(9):
                line.append(('*' if bad[r][c] else ' ') + grid[r][c])
            out.append(''.join(line))

        if case != t - 1:
            out.append('')

    sys.stdout.write('\n'.join(out))

